#[esp_rtos::main]
async fn main(_spawner: Spawner) -> ! {
    let state = setup().await;

    loop {
        log::info!(
            "sd: {}",
            if state.sd_mounted {
                "mounted and readable"
            } else {
                "not mounted - insert a FAT-formatted card in the TF socket and reset"
            }
        );
        Timer::after(Duration::from_secs(10)).await;
    }
}
